{"ASK_TRADE","role=soldier_nco|st=neutral,careful",{"No deals, soldier, civilians included"}},
{"ASK_TRADE","role=soldier_green|st=neutral,careful",{"I have some candy, I'd trade it for something useful, if that's okay?"}},
{"ASK_TRADE","role=mercenary|st=neutral,careful",{"I'll trade for the right price"}},
