{"ASK_TRADE","reg=military,elite|st=neutral",{"Not authorized to trade"}},
{"ASK_TRADE","reg=outlaw,raider,gang,club,crime,prison|st=friendly",{"Trade? Now we're talking, what do you have, and how much do I want it?","Everything's for sale, even me, what are you buying?","Name your price, I'll name mine, then we'll fight over the middle"}},
{"ASK_TRADE","reg=outlaw,raider,gang,club,crime,prison|st=neutral",{"What's in it for me?","Show me something shiny"}},
{"ASK_TRADE","tmp=veteran|st=friendly",{"State terms"}},
